"""Compose the captured cashout dependency catalog, never production rows."""
import json,re
from pathlib import Path
HERE=Path(__file__).resolve().parent
def records(name):return [json.loads(line) for line in (HERE/(name+'.jsonl')).read_text().splitlines() if line]
def quote(v):return '"'+v.replace('"','""')+'"'
def literal(v):return "'"+v.replace("'","''")+"'"
def schema():
 tables=records('tables');functions=list({f['signature']:f for f in records('functions')+records('helpers')}.values());meta=records('metadata')[0]
 out=['SET check_function_bodies=off;','CREATE SCHEMA IF NOT EXISTS extensions;','CREATE SCHEMA IF NOT EXISTS smarter_private;', 'CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;', 'CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;', 'CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions;', 'SET search_path=public,extensions;']
 for typ in meta['types']:out.append('CREATE TYPE '+quote(typ['schema'])+'.'+quote(typ['name'])+' AS ENUM('+','.join(literal(v) for v in typ['labels'])+');')
 defaults=[];constraints=[];indexes=[];sequences=set()
 for t in tables:
  table=quote(t['schema_name'])+'.'+quote(t['name']);cols=[]
  for c in t['columns']:
   line=quote(c['name'])+' '+c['type']
   if c['generated']:line+=' GENERATED ALWAYS AS ('+c['default']+') STORED'
   elif c['identity']:line+=' GENERATED BY DEFAULT AS IDENTITY'
   elif c['default']:
    defaults.append('ALTER TABLE '+table+' ALTER COLUMN '+quote(c['name'])+' SET DEFAULT '+c['default']+';')
    sequences.update(re.findall(r"nextval\('([^']+)'(?:::regclass)?\)",c['default']))
   if c['notnull']:line+=' NOT NULL'
   cols.append(line)
  out.append('CREATE TABLE '+table+'('+',\n'.join(cols)+');')
  for c in t['constraints'] or []:constraints.append((c['type']=='f','ALTER TABLE '+table+' ADD CONSTRAINT '+quote(c['name'])+' '+c['definition']+';'))
  indexes.extend(i+';' for i in t['indexes'] or [])
 for f in functions:sequences.update(re.findall(r"nextval\('([^']+)'(?:::regclass)?\)",f['definition']))
 for seq in sorted(sequences):out.append('CREATE SEQUENCE '+'.'.join(quote(x) for x in seq.split('.'))+';')
 for f in functions:
  signature=(f['schema_name']+'.' if not f['signature'].startswith(f['schema_name']+'.') else '')+f['signature']
  out.extend([f['definition']+';', 'ALTER FUNCTION '+signature+' OWNER TO '+quote(f['owner'])+';', 'REVOKE ALL ON FUNCTION '+signature+' FROM PUBLIC,anon,authenticated,service_role;'])
  roles=f['execute_roles']
  if isinstance(roles,str):roles=[r for r in roles.strip('{}').split(',') if r]
  if roles:out.append('GRANT EXECUTE ON FUNCTION '+signature+' TO '+','.join(quote(r) for r in roles)+';')
 out+=defaults+[c[1] for c in constraints if not c[0]]+indexes+[c[1] for c in constraints if c[0]]
 for t in tables:
  table=quote(t['schema_name'])+'.'+quote(t['name'])
  if t['rls']:out.append('ALTER TABLE '+table+' ENABLE ROW LEVEL SECURITY;')
  if t['force_rls']:out.append('ALTER TABLE '+table+' FORCE ROW LEVEL SECURITY;')
  for p in t['policies'] or []:
   cmd={'r':'SELECT','a':'INSERT','w':'UPDATE','d':'DELETE','*':'ALL'}[p['command']]
   out.append('CREATE POLICY '+quote(p['name'])+' ON '+table+' AS '+('PERMISSIVE' if p['permissive'] else 'RESTRICTIVE')+' FOR '+cmd+' TO '+','.join('PUBLIC' if r=='public' else quote(r) for r in p['roles'])+(' USING ('+p['using']+')' if p['using'] else '')+(' WITH CHECK ('+p['check']+')' if p['check'] else '')+';')
  # Reproduce the captured direct client/service table privileges. No client writes are added.
  for role,acl in re.findall(r'(anon|authenticated|service_role|)=([a-zA-Z]*)/',t['acl'] or ''):
   names={'r':'SELECT','a':'INSERT','w':'UPDATE','d':'DELETE','D':'TRUNCATE','x':'REFERENCES','t':'TRIGGER','m':'MAINTAIN'}
   rights=[v for k,v in names.items() if k in acl]
   if rights:out.append('GRANT '+','.join(rights)+' ON '+table+' TO '+('PUBLIC' if not role else quote(role))+';')
 for t in records('triggers'):
  out.append(t['definition']+';')
  if t['enabled']=='D':out.append('ALTER TABLE '+t['table']+' DISABLE TRIGGER '+quote(t['name'])+';')
  elif t['enabled']=='A':out.append('ALTER TABLE '+t['table']+' ENABLE ALWAYS TRIGGER '+quote(t['name'])+';')
  elif t['enabled']=='R':out.append('ALTER TABLE '+t['table']+' ENABLE REPLICA TRIGGER '+quote(t['name'])+';')
 out.append('GRANT USAGE ON SCHEMA public,smarter_private,extensions TO anon,authenticated,service_role;')
 return '\n'.join(out)
if __name__=='__main__':print(schema())
